// Maan lijiye aapka data 'final_report' naam ki field mein hai
const rawData = items[0].json.final_report;

try {
  // Agar Gemini ne JSON string bheji hai toh use object mein badle
  return JSON.parse(rawData);
} catch (e) {
  // Agar wo simple text hai, toh use ek JSON object mein wrap karein
  return {
    "weather_report": rawData
  };
}

// 1. Gemini se aaya hua raw text nikalte hain
let rawText = items[0].json.weather_report;

// 2. Faltu ke markdown symbols (```json aur ```) ko hatate hain
let cleanText = rawText.replace(/```json|```/g, "").trim();

// 3. Is saaf text ko asli JSON (Object) mein badalte hain
let finalJson = JSON.parse(cleanText);

// 4. Ise n8n ke output ke liye return karte hain
return finalJson;
